{{(() => {
  const r = GetCodReport.data;
  if (!r || !r.totals) return 'Изберете период.';
  const t = r.totals;
  const who = MerchantSelect.selectedOptionValue && MerchantSelect.selectedOptionValue !== 'all' ? (MerchantSelect.selectedOptionLabel || '') : 'всички търговци';
  const e = (n) => (Number(n) || 0).toFixed(2) + ' €';
  return `Период ${r.period.label} · ${who} · ${t.orders} поръчки · НП ${e(t.total)} (в брой ${e(t.cash)}, с карта ${e(t.card)}) · Приходи на Фулфилия ООД ${e(t.revenue)} (доставки ${e(t.delivery)} + комисионна ${e(t.fee)}) · За търговците ${e(t.owed)}`;
})()}}
